```

```
#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

// Definição de uma restrição
struct Restriction {
    string name;
    vector<string> keywords;
};

// Função para verificar se um currículo atende às restrições
bool isCurriculumValid(const vector<Restriction>& restrictions, const string& curriculum) {
    for (const auto& restriction : restrictions) {
        bool valid = true;
        for (const auto& keyword : restriction.keywords) {
            if (curriculum.find(keyword) != string::npos) {
                valid = false;
                break;
            }
        }
        if (valid) {
            return false;
        }
    }
    return true;
}

int main() {
    vector<Restriction> restrictions;
    // Adicionando restrições
    restrictions.push_back({"Saúde", {"Engenharia Civil"}});
    restrictions.push_back({"Tecnologia", {"Engenharia Civil"}});

    string curriculum;
    cout << "Digite o currículo: ";
    getline(cin, curriculum);

    if (isCurriculumValid(restrictions, curriculum)) {
        cout << "Seu currículo atende às restrições: Sim" << endl;
    } else {
        cout << "Seu currículo atende às restrições: Não" << endl;
    }

    return 0;
}
```

