```
#include <iostream>
#include <string>

using namespace std;

int main() {
    string word;
    cout << "Digite uma palavra: ";
    cin >> word;

    bool is_palindrome = true;
    for (int i = 0; i < word.size() / 2; i++) {
        if (word[i] != word[word.size() - 1 - i]) {
            is_palindrome = false;
